CREATE TABLE ibexa_object_state_group (id INT AUTO_INCREMENT NOT NULL, default_language_id BIGINT DEFAULT 0 NOT NULL, identifier VARCHAR(45) DEFAULT '' NOT NULL, language_mask BIGINT DEFAULT 0 NOT NULL, INDEX ibexa_object_state_group_lmask (language_mask), UNIQUE INDEX ibexa_object_state_group_identifier (identifier), PRIMARY KEY(id)) DEFAULT CHARACTER SET utf8 COLLATE `utf8_unicode_ci` ENGINE = InnoDB;
